from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/headers")
async def read_headers(x_user_agent: str = Header()):
    return {"x_user_agent": x_user_agent}

client = TestClient(app)

def test_header_underscores_not_accepted_by_default():
    # By default, convert_underscores=True. 
    # It should look for 'x-user-agent'. 
    # Sending 'x_user_agent' should result in a validation error (missing header)
    # because it should NOT fallback to the underscore version.
    response = client.get("/headers", headers={"x_user_agent": "test-value"})
    assert response.status_code == 422

def test_header_hyphens_accepted_by_default():
    response = client.get("/headers", headers={"x-user-agent": "test-value"})
    assert response.status_code == 200
    assert response.json() == {"x_user_agent": "test-value"}

def test_header_underscores_accepted_when_convert_underscores_false():
    @app.get("/headers-no-convert")
    async def read_headers_no_convert(x_user_agent: str = Header(convert_underscores=False)):
        return {"x_user_agent": x_user_agent}

    response = client.get("/headers-no-convert", headers={"x_user_agent": "test-value"})
    assert response.status_code == 200
    assert response.json() == {"x_user_agent": "test-value"}

